F_set findFirst(const string ss, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = true;
	f_set.left = ss;
	//空串的First集只含'@'
	if (ss.empty()) {
		f_set.right.insert('@');
		return f_set;
	}
	//首符号不是任何规则的左部，则为终结符或'@'，First集即其本身
	bool is_non_terminal = false;
	for (const rule& r : rules) {
		if (r.left == ss[0]) { is_non_terminal = true; break; }
	}
	if (!is_non_terminal) {
		f_set.right.insert(ss[0]);
		return f_set;
	}
	//首符号为非终结符，遍历其所有产生式右部
	for (const rule& r : rules) {
		if (r.left != ss[0]) continue;
		for (const string& rp : r.right) {
			if (rp == "@") {
				f_set.right.insert('@');
				continue;
			}
			//依次扫描右部各符号，遇到不能推出空的符号即停止
			bool all_nullable = true;
			for (size_t i = 0; i < rp.size(); i++) {
				F_set sub = findFirst(string(1, rp[i]), rules);
				for (char c : sub.right) {
					if (c != '@') f_set.right.insert(c);
				}
				if (!sub.right.count('@')) {
					all_nullable = false;
					break;
				}
			}
			if (all_nullable) f_set.right.insert('@');
		}
	}
	return f_set;
}

